// Generated by the website's scripts/build-peppol-ubl-check.ts from its own copy of these tests; edit there.
import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { corpusHash } from "./multi-error/corpus";
import { decodeVerdicts, describeDifferences } from "./multi-error/compare";
import { FAMILY_PROFILE, NO_SCENARIO_VERDICT, familyFindings, familyRules, loadFamilyFixture, type Family, type FixtureKind } from "./multi-error/families";

/**
 * Every rule set's multi-fault fixtures, recorded by `bun scripts/compare-multi-error-invoices.ts` against the official
 * files each one is published as (families.ts): the repeated-block corpus (`--repeated --record-repeated`: every
 * element repeated once, plus one fault inside either copy) for Peppol BIS 3.0.22, EN 16931, SI-UBL 2.0 / NLCIUS and
 * XRechnung, and the seeded multi-error corpus (`--record-national`: 2–8 faults at once) for the last three (Peppol's
 * is multi-error-verdicts.json, multi-error-parity.test.ts; the 3.1.0 draft's are site-only, next/). Each invoice is
 * rebuilt from the stored bases (its recorded hash proves it's the same one) and compared with the recording run's own
 * comparator, rule by rule and on the verdict; an XRechnung that KoSIT rejects for want of a scenario must fail here too.
 */
const DIR = resolve(__dirname, "fixtures/schematron-parity");
const SETS: [FixtureKind, Family][] = [
  ["repeated", "peppol"],
  ["repeated", "en16931"],
  ["repeated", "nl"],
  ["repeated", "xr"],
  ["national-multi", "en16931"],
  ["national-multi", "nl"],
  ["national-multi", "xr"],
];

describe.each(SETS)("official verdicts on the %s fixture of %s", (kind, family) => {
  const { fixture, bases, corpus, ids } = loadFamilyFixture(DIR, kind, family);

  it("rebuilds every recorded invoice from the stored bases, for the family's profile", () => {
    expect(fixture.family).toBe(family);
    expect(fixture.profile).toBe(FAMILY_PROFILE[family]);
    for (const b of bases) expect({ base: b.name, hash: corpusHash(b.xml) }).toEqual({ base: b.name, hash: fixture.bases[b.name] });
    expect(ids.filter((id) => corpusHash(corpus.get(id)?.xml ?? "") !== fixture.cases[id]!.hash)).toEqual([]);
  });

  it("covers both syntaxes, passing and failing invoices", () => {
    const xmls = ids.map((id) => corpus.get(id)!.xml);
    expect(xmls.filter((x) => x.includes("CrossIndustryInvoice")).length).toBeGreaterThan(5);
    expect(xmls.filter((x) => !x.includes("CrossIndustryInvoice")).length).toBeGreaterThan(5);
    const verdicts = ids.map((id) => fixture.cases[id]!["3.0.22"]).filter((v) => v !== NO_SCENARIO_VERDICT);
    expect(verdicts.some((v) => !Object.values(decodeVerdicts(v)).includes("error"))).toBe(true);
    expect(verdicts.some((v) => Object.values(decodeVerdicts(v)).includes("error"))).toBe(true);
    if (kind === "national-multi") expect(ids.length).toBeGreaterThanOrEqual(300);
    // the seeded corpus changes identifiers; repeating an element never does
    if (family === "xr" && kind === "national-multi") expect(ids.some((id) => fixture.cases[id]!["3.0.22"] === NO_SCENARIO_VERDICT)).toBe(true);
  });

  it("matches the official files rule by rule and on the verdict", () => {
    const rules = familyRules(family);
    const differences = ids.flatMap((id) => {
      const c = corpus.get(id)!;
      const recorded = fixture.cases[id]!["3.0.22"];
      const findings = familyFindings(family, c.xml);
      if (recorded === NO_SCENARIO_VERDICT)
        return findings.some((f) => f.ruleId === "IV-DE-02" && f.severity === "error") ? [] : [{ id, faults: c.faults, rules: ["KoSIT rejects it (no scenario), ours doesn't"] }];
      const d = describeDifferences(id, c.faults, decodeVerdicts(recorded), findings, rules);
      return d ? [d] : [];
    });
    expect(differences).toEqual([]);
  });
});

it("has a fixture for every family and corpus", () => {
  for (const [kind, family] of SETS) expect(existsSync(resolve(DIR, kind, `${family}.json`))).toBe(true);
});
